from src.nodes.base import BaseNode
from src.runtime.assets.realization import get_asset_material_mapper
import json

class Hou_Mcp_Asset_Materials(BaseNode):
    name = "hou_mcp_asset_materials"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("asset_json", "string", widget_type="text")
        self.add_input("renderer",   "string", widget_type="text", default="usd_preview_surface")
        self.add_output("mapping_result_json", "string")
        self.add_output("profiles_json",       "string")
        self.add_output("material_count",      "int")
        self.add_output("mapping_ok",          "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        asset_json = inputs.get("asset_json", "") or ""
        renderer   = str(inputs.get("renderer") or "usd_preview_surface")

        if not asset_json.strip():
            self.log_error("No asset_json provided.")
            return {"mapping_result_json": "{}", "profiles_json": "[]", "material_count": 0, "mapping_ok": False, "exec_out": True}

        try:
            asset = json.loads(asset_json)
        except Exception as exc:
            self.log_error(f"Failed to parse asset_json: {exc}")
            return {"mapping_result_json": "{}", "profiles_json": "[]", "material_count": 0, "mapping_ok": False, "exec_out": True}

        try:
            result = get_asset_material_mapper().map_materials(asset, renderer)
            self.log_info(f"Material mapping: {result.material_count} profiles for renderer={renderer} ok={result.ok}")
            return {
                "mapping_result_json": json.dumps(result.to_dict(), sort_keys=True, default=str),
                "profiles_json":       json.dumps([p.to_dict() for p in result.profiles], sort_keys=True, default=str),
                "material_count":      result.material_count,
                "mapping_ok":          result.ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Material mapping failed: {exc}")
            return {"mapping_result_json": "{}", "profiles_json": "[]", "material_count": 0, "mapping_ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Materials
